'use strict';
const app=document.querySelector('#app'),modalRoot=document.querySelector('#modal-root');
const state={dataMode:'frozen',dataState:'ready',loadTimer:null,view:'board',selected:'sim-001',query:'',filter:'全部',sort:'最近活动',archive:false,menu:null,periods:{},tab:'订单列表',order:0,tf:'5m',collapsed:false,stopped:new Set(),cancelled:new Set(),restored:new Set(),live:{},drawer:null};
const labels={running:'运行中',delayed:'行情延迟',recovering:'恢复中',market_closed:'休市等待',preparing:'准备就绪',draft:'草稿',completed:'运行完成',failed:'执行失败',incomplete_close:'未完成收尾',stopping:'停止中',cancelled:'已取消',unknown:'状态未取得'};
const liveStates=['running','delayed','recovering','market_closed'];
const archived=new Set(['sim-004','sim-005']);
const esc=v=>String(v??'未提供').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(text,action,cls='',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const badge=s=>`<span class="badge ${s}">${esc(labels[s]||s)}</span>`;
const simBy=id=>DATA.SIMS.find(x=>x.id===id);
function status(sim){return state.cancelled.has(sim.id)?'cancelled':state.stopped.has(sim.id)?'stopping':state.live[sim.id]||sim.status;}
function announce(text){document.querySelector('#announcer').textContent=text;clearTimeout(announce.timer);announce.timer=setTimeout(()=>document.querySelector('#announcer').textContent='',3500);}
function metric(label,value){return `<div class="metric"><small>${label}</small><strong class="mono ${String(value).startsWith('-')?'negative':String(value).startsWith('+')?'positive':''}">${esc(value)}</strong></div>`;}
function metrics(sim){const m=sim.metrics;return `<div class="metrics">${m?[['净利润',m.netPnl],['最大回撤',m.maxDrawdown],['胜率',m.winRate],['订单数量',m.orders],['夏普',m.sharpe],['盈亏比',m.profitFactor]].map(x=>metric(...x)).join(''):`<div class="muted fullvalue">${esc(sim.metricsNote||'未提供 · 六项表现不可计算')}</div>`}</div>`;}
function spark(seed=3,large=false){let n=seed;const pts=[];for(let i=0;i<48;i++){n=(n*9301+49297)%233280;pts.push([i*6,63-i*.7+(n/233280-.5)*20]);}return `<svg class="spark" viewBox="0 0 282 90" preserveAspectRatio="none" role="img" aria-label="示例权益曲线"><path d="M${pts.map(p=>p.join(',')).join(' L')} L282,90 L0,90 Z" fill="#34d3990b"/><polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#34d399" stroke-width="1.5" vector-effect="non-scaling-stroke"/><path d="M0 82H282" stroke="#ffffff10"/></svg>`;}
function facts(sim){return `<div class="kv">${[['状态',labels[status(sim)]],['run_kind',sim.runKind],['策略 / 版本',sim.strategy+':'+sim.version],['合约',sim.contract],['session',sim.session],['运行时长',sim.runDuration],['持仓',sim.position?.text],['最近行情',sim.lastMarketTime?.text],['当日已确认亏损',sim.todayLoss?.text],['日限额剩余',sim.dailyLimitLeft?.text]].map(([k,v])=>`<div><small>${k}</small><p class="mono">${esc(v)}</p></div>`).join('')}</div>`;}
function row(sim){const s=status(sim),pending=['preparing','draft','cancelled'].includes(s),isArchive=archived.has(sim.id)&&!state.restored.has(sim.id),period=state.periods[sim.id]||'本周',canOpen=Boolean(DATA.SIM_DATA[sim.id])&&!pending;return `<article class="card" id="sim-row-${sim.id}" data-state="${s}"><div class="${pending?'pendingrow':'cardrow'}"><div><div class="cardtitle"><h3>${esc(sim.name)}</h3>${badge(s)}${sim.id==='sim-001'?'<span class="badge negative">已接入</span>':''}${isArchive?'<span class="deprecated">已废弃</span>':''}</div><div class="meta"><span>${esc(sim.strategy)}</span><span class="mono sky">${esc(sim.version)}</span><span class="mono">${esc(sim.contract)}</span>${!pending?`<span>${sim.runDuration?'已运行 '+esc(sim.runDuration):'终止于 '+esc(sim.endedAt||'未提供')}</span>`:''}</div>${!pending?`<div class="periods">${['今日','本周','本月'].map(p=>button(`${p} <span class="mono ${sim.metrics?'positive':''}">${esc(p==='今日'?sim.today:p==='本周'?sim.last7:sim.metrics?.netPnl||'未提供')}</span>`,'period','',`data-id="${sim.id}" data-period="${p}" aria-pressed="${period===p}"`)).join('')}</div>`:''}</div>${!pending?metrics(sim)+`<div class="equityblock"><div class="equityhead"><span>权益曲线 · ${period}</span><span>${esc(sim.metrics?.orders||'未提供')} 单</span></div>${sim.metrics?spark(sim.seed||3):'<div class="empty">证据不足，无法绘制</div>'}<div class="equitydates mono"><span>${esc(sim.startDate||'未提供')}</span>${sim.metrics?`<span class="negative">最大回撤 ${esc(sim.metrics.maxDrawdown)}</span>`:''}<span>${esc(sim.endDate||'未提供')}</span></div></div>`:''}<div class="cardactions">${pending?(s==='cancelled'?button('恢复待启动','restore-pending','',`data-id="${sim.id}"`):button('开始','start','primary',`data-id="${sim.id}"`)):canOpen?button(isArchive?'打开复盘':'打开工作台','workbench','primary',`data-id="${sim.id}"`):button('暂无工作台','', '', 'disabled')}<div class="rowmenu">${button('更多','menu','',`data-id="${sim.id}" aria-expanded="${state.menu===sim.id}"`)}${state.menu===sim.id?`<div class="menu" role="menu">${button(pending?'查看配置':'查看详情','detail','',`data-id="${sim.id}" role="menuitem"`)}${pending&&s!=='cancelled'?button('取消本次启动','cancel-pending','danger',`data-id="${sim.id}" role="menuitem"`):''}${isArchive?button('恢复到模拟记录','restore','',`data-id="${sim.id}" role="menuitem"`):!pending?button('归档记录','archive','',`data-id="${sim.id}" role="menuitem"`):''}${liveStates.includes(s)?`<label class="muted">演示运行状态<select class="statepick" data-live="${sim.id}" aria-label="${esc(sim.name)}的演示运行状态">${liveStates.map(t=>`<option value="${t}" ${t===s?'selected':''}>${labels[t]}</option>`).join('')}</select></label>`:''}</div>`:''}</div></div></div></article>`;}
function filtered(){let sims=DATA.SIMS.filter(x=>(x.name+x.strategy+x.contract).toLowerCase().includes(state.query.toLowerCase()));if(state.filter==='隔离')sims=sims.filter(x=>status(x)==='isolated');if(state.filter==='未完成')sims=sims.filter(x=>['incomplete_close','stopping'].includes(status(x)));if(state.filter==='部分已确认')sims=sims.filter(x=>x.evidence==='partial');if(state.sort==='名称')sims.sort((a,b)=>a.name.localeCompare(b.name,'zh'));if(state.sort==='按表现排序')sims.sort((a,b)=>a.metrics&&b.metrics?Number(b.metrics.netPnl.replace(/[^\d.-]/g,''))-Number(a.metrics.netPnl.replace(/[^\d.-]/g,'')):a.metrics?-1:b.metrics?1:0);return sims;}
function dataDemoControl(){const chosen=state.dataMode==='frozen'?'frozen':state.dataState;return `<label class="prototype-demo">数据状态（原型演示）<select data-demo-state aria-label="数据状态（原型演示）">${[['frozen','冻结示例'],['ready','正常（本地演示）'],['loading','正在加载'],['empty','暂无记录'],['error','加载失败'],['unknown','结果未取得']].map(([value,label])=>`<option value="${value}" ${chosen===value?'selected':''}>${label}</option>`).join('')}</select></label>`;}
function enterDataState(value){clearTimeout(state.loadTimer);state.loadTimer=null;state.dataMode=value==='frozen'?'frozen':'live-demo';state.dataState=value==='frozen'?'ready':value;state.menu=null;render();if(value==='loading')state.loadTimer=setTimeout(()=>{if(state.dataMode==='live-demo'&&state.dataState==='loading'){state.dataState='ready';state.loadTimer=null;render();}},2000);}
function dataPanel(view){const name=view==='board'?'模拟记录':'运行详情',settings={loading:['正在加载'+name,'正在等待本地示例完成。',''],empty:['暂无'+name,'当前示例没有可展示的记录。','恢复示例记录'],error:[name+'读取失败','本地错误演示：未取得可用记录，请重试。','重试'],unknown:['运行结果尚未取得','暂时无法确认记录或执行结果；这不代表没有记录或运行成功。','重新读取']},[heading,message,action]=settings[state.dataState];return `<section class="data-state-panel" data-load-state="${state.dataState}" role="status" aria-live="polite" aria-busy="${state.dataState==='loading'}"><h2>${esc(heading)}</h2><p>${esc(message)}</p><div class="inlineactions">${action?button(action,state.dataState==='empty'?'data-restore':'data-retry','primary'):''}${button('返回冻结示例','data-frozen')}</div><small>本地原型演示，不连接真实服务或存储。</small></section>`;}
function renderBoard(){const retainedSearch=app.querySelector('input[type=search]'),searchFocused=retainedSearch===document.activeElement;const sims=filtered(),active=sims.filter(x=>!archived.has(x.id)||state.restored.has(x.id)),history=sims.filter(x=>archived.has(x.id)&&!state.restored.has(x.id)),groups=[['待启动',active.filter(x=>['preparing','draft','cancelled'].includes(status(x)))],['当前运行中',active.filter(x=>liveStates.includes(status(x))||status(x)==='stopping')],['已停止',active.filter(x=>!['preparing','draft','cancelled',...liveStates,'stopping'].includes(status(x)))]];app.innerHTML=`<header class="topbar"><div class="nav"><span class="brand">PaperBuilder</span>${button('策略列表','not-in-scope')}${button('模拟记录','board','', 'aria-current="page"')}${button('实盘驾驶舱','not-in-scope')}</div><div class="topright"><span>NQ <span class="positive">[已就绪]</span></span><span>ES <span class="amber">[更新至 7 天前]</span></span><span>实时 <span class="positive">[可用]</span></span></div></header><main id="main" tabindex="-1" class="board" data-page="board"><div class="heading"><div><div class="titleline"><h1>模拟记录</h1><span class="slots mono">5/5</span></div><div class="kicker">SIMULATION RECORDS</div></div><div class="toolbar"><div class="segmented" role="group" aria-label="异常筛选"><span>异常筛选</span>${['全部','隔离','未完成','部分已确认'].map(x=>button(x,'filter','',`data-filter="${x}" aria-pressed="${state.filter===x}"`)).join('')}</div><input type="search" aria-label="搜索模拟、策略或合约" placeholder="搜索模拟、策略或合约" value="${esc(state.query)}"><label class="muted">排序 <select id="sort" aria-label="模拟记录排序">${['最近活动','名称','按表现排序'].map(x=>`<option ${x===state.sort?'selected':''}>${x}</option>`).join('')}</select></label>${dataDemoControl()}</div></div>${state.dataState!=='ready'?dataPanel('board'):sims.length?groups.map(([name,list],i)=>`<section class="group" aria-label="${name}"><div class="grouphead"><h2>${name}</h2><span class="count">${list.length}</span></div><div class="${i===0?'pendinggrid':''}">${list.length?list.map(row).join(''):`<div class="empty">暂无${name}的模拟</div>`}</div></section>`).join(''):'<div class="empty"><h2>没有符合条件的模拟</h2><p>调整搜索或异常筛选条件</p></div>'}${state.dataState==='ready'?`<details class="archive" ${state.archive?'open':''}><summary><h2>历史/归档</h2><span class="count">${history.length}</span></summary>${state.archive?(history.length?history.map(row).join(''):'<div class="empty">没有归档的记录</div>'):''}</details>`:''}<footer class="sample">示例数据，仅用于设计评审 · 不代表真实 PaperBuilder 业务数据</footer></main>`;if(retainedSearch){const replacement=app.querySelector('input[type=search]');replacement.replaceWith(retainedSearch);retainedSearch.value=state.query;if(searchFocused)retainedSearch.focus();}app.querySelector('details.archive')?.addEventListener('toggle',e=>{if(!e.target.isConnected||state.archive===e.target.open)return;state.archive=e.target.open;render();});}
function chart(){let seed=24680,price=30015;const rand=()=>{seed=(seed*9301+49297)%233280;return seed/233280;},bars=[];for(let i=0;i<54;i++){const o=price,c=o+(30025+Math.sin(i/8)*26+Math.sin(i/3.2)*8-price)*.28+(rand()-.5)*16,h=Math.max(o,c)+rand()*10+2,l=Math.min(o,c)-rand()*10-2;bars.push({o,c,h,l,vol:40+rand()*120});price=c;}const ys=v=>305-(v-29960)*2,x=i=>20+i*16;return `<svg viewBox="0 0 960 410" preserveAspectRatio="none" role="img" aria-label="固定示例 Footprint 图表，时间周期仅改变选择状态"><g stroke="#ffffff0a">${[60,120,180,240,300,360].map(y=>`<path d="M0 ${y}H905"/>`).join('')}${[80,240,400,560,720,880].map(xx=>`<path d="M${xx} 0V370"/>`).join('')}</g>${bars.map((b,i)=>{const col=b.c>=b.o?'#34d399':'#fb7185';return `<path d="M${x(i)} ${ys(b.h)}V${ys(b.l)}" stroke="${col}"/><rect x="${x(i)-3}" y="${Math.min(ys(b.o),ys(b.c))}" width="6" height="${Math.max(2,Math.abs(ys(b.o)-ys(b.c)))}" fill="${col}"/><rect x="${x(i)-4}" y="${385-b.vol*.18}" width="8" height="${b.vol*.18}" fill="${col}33"/>`;}).join('')}<polyline points="${bars.map((b,i)=>`${x(i)},${ys(b.c)-28}`).join(' ')}" stroke="#38bdf880" fill="none"/><polyline points="${bars.map((b,i)=>`${x(i)},${ys(b.c)+35}`).join(' ')}" stroke="#38bdf850" fill="none"/>${!state.stopped.has(state.selected)&&liveStates.includes(status(simBy(state.selected)))?`<g data-chart-overlay="live"><path d="M0 164H900" stroke="#34d399" stroke-dasharray="4 3"/><path d="M0 238H900" stroke="#fb7185" stroke-dasharray="4 3"/><rect x="720" y="146" width="165" height="22" fill="#103629"/><text x="730" y="161" fill="#6ee7b7" font-size="11">多 1 手 · +$87.50</text></g>`:''}<g fill="#8190a4" font-size="10" font-family="monospace">${[30060,30030,30000,29970].map((v,i)=>`<text x="909" y="${ys(v)}">${v}</text>`).join('')}${['17:10','17:40','18:10','18:40','19:10','19:40'].map((t,i)=>`<text x="${20+i*160}" y="406">${t}</text>`).join('')}</g></svg>`;}
function orderDetail(){const o=DATA.ORDERS[state.order];return `<h3>${esc(o.title)}</h3><div class="kv">${[['入场方式',o.entryKind],['入场价格',o.entryPrice],['持仓时间',o.holdTime],['盈亏',o.pnl===null?'未成交 · 不适用':o.pnl],['离场逻辑',o.exitLogic],['限价原因',o.limitReason||'市价委托，不适用']].map(([k,v])=>`<div><small>${k}</small><p class="mono">${esc(v)}</p></div>`).join('')}</div><h3 style="margin-top:18px">方向判断</h3>${o.dirPoints.map(p=>`<div class="checkrow"><span>${esc(p.text)}</span><span class="${p.ok?'positive':'amber'}">${p.ok?'满足':'未满足'}</span></div>`).join('')}<h3 style="margin-top:18px">入场判断</h3>${o.entryPoints.map(p=>`<div class="checkrow"><span>${esc(p.text)}</span><span class="${p.ok?'positive':'amber'}">${p.ok?'满足':'未满足'}</span></div>`).join('')}<div class="kv">${[['止损',o.slTicks+' · '+o.slLogic],['止盈',o.tpTicks+' · '+o.tpLogic]].map(([k,v])=>`<div><small>${k}</small><p>${esc(v)}</p></div>`).join('')}</div>`;}
function renderWorkbench(){const sim=simBy(state.selected),s=state.dataState==='ready'?status(sim):'unknown',isLive=liveStates.includes(s),stopping=s==='stopping';app.innerHTML=`<div class="workbench" data-page="workbench"><header class="wbheader"><div class="wbidentity">${button('返回','board','compact','aria-label="返回模拟记录"')}<div><div class="inlineactions"><h1>${esc(sim.name)}</h1><span class="mono sky">${esc(sim.strategy)}:${esc(sim.version)}</span><span class="tooltipwrap">${button(badge(s),'health','compact','aria-label="查看运行监控"')}<span class="tooltip" role="tooltip"><strong>运行监控</strong><br>${state.dataState==='ready'?sim.health.map(x=>`${esc(x.label)} · ${esc(x.state)}`).join('<br>'):'运行事实尚未取得'}<br>${state.dataState==='ready'?esc(sim.lastMarketTime?.text):'未取得'}</span></span>${archived.has(sim.id)&&!state.restored.has(sim.id)?'<span class="badge sky">历史回放</span>':''}</div><div class="meta mono">${esc(sim.contract)} · ${esc(sim.session)} · ${esc(sim.runId)}</div></div></div><div class="inlineactions">${dataDemoControl()}${button('刷新','refresh')}${button('业务日志','log')}${isLive?button('正常停止','normal','','data-stop="normal"')+button('紧急停止','emergency','danger','data-stop="emergency"'):stopping?'<span class="amber">只读回看 · 停止中</span>':'<span class="muted">只读回看</span>'}</div></header><main id="main" tabindex="-1" class="wbbody">${state.dataState!=='ready'?dataPanel('workbench'):`<section class="wbleft"><div class="charttoolbar"><div class="tfs">${['1m','5m','15m','1h'].map(t=>button(t,'tf','',`data-tf="${t}" aria-pressed="${state.tf===t}"`)).join('')}</div><span>Footprint · ${esc(sim.contract)} <span class="mono">最新 30030.25</span></span></div><div class="chart"><span class="chartlabel">${esc(sim.contract)} · 固定示例</span>${chart()}</div><section class="orderpanel ${state.collapsed?'collapsed':''}"><div class="tabs"><div class="tabbuttons" role="tablist" aria-label="模拟详情">${['订单列表','最新事件','风控事件'].map(t=>button(t,'tab','',`role="tab" data-tab="${t}" aria-selected="${state.tab===t}"`)).join('')}</div>${button(state.collapsed?'展开':'收起','collapse','compact',`aria-expanded="${!state.collapsed}" aria-label="${state.collapsed?'展开':'收起'}订单面板"`)}</div>${state.collapsed?'':state.tab==='订单列表'?`<div class="orderbody"><div class="orderlist">${DATA.ORDERS.map((o,i)=>button(`<small class="mono">${esc(o.entryPrice)} · ${esc(o.dir)}</small><p>${esc(o.title)}</p><div class="inlineactions"><small>${esc(o.status)}</small><span class="mono ${String(o.pnl).startsWith('-')?'negative':'positive'}">${o.pnl===null?'未成交':esc(o.pnl)}</span></div>`,'order','order',`data-order="${i}" aria-pressed="${state.order===i}"`)).join('')}</div><div class="orderdetail">${orderDetail()}</div></div>`:state.tab==='最新事件'?`<div class="timeline"><p><small>运行记录</small><br><span class="mono">${esc(sim.runId)}</span></p><p>${esc(labels[s])} · ${esc(sim.lastMarketTime?.text)}</p>${s==='failed'?'<p class="negative">执行失败；详细原因以原始证据为准，未取得字段不补造。</p>':''}</div>`:'<div class="empty">暂无风险事件<br><small>此示例未提供新的风控事件。</small></div>'}</section></section><aside class="sidebar"><section><h2>策略表现</h2>${metrics(sim)}${sim.metrics?spark(5):'<div class="empty">证据不足，无法绘制</div>'}</section><section><h2>模拟账户</h2><div class="kv">${[['初始资金',DATA.ACCOUNT.initial],['真实权益',DATA.ACCOUNT.realEquity],['已报告累计',DATA.ACCOUNT.reportedCum],['缺失影响',DATA.ACCOUNT.missingImpact]].map(([k,v])=>`<div><small>${k}</small><p class="mono">${esc(v)}</p></div>`).join('')}</div><div class="note">模拟保证金 · 示例数据，不代表真实账户。</div></section><section><h2>策略实时逻辑</h2>${isLive?DATA.ORDERS[0].dirPoints.map(p=>`<div class="checkrow"><span>${esc(p.text)}</span><span class="positive">满足</span></div>`).join(''):`<div class="note">${stopping?'停止中 · 不再产生新模拟意图':'只读回看 · 不推进策略'}</div>`}</section><section><h2>运行事实</h2>${facts(sim)}</section></aside>`}</main><footer class="wbfoot">本地交互原型 · 不连接真实交易或存储</footer></div>`;}
function render(){
 const active=document.activeElement,oldPage=app.querySelector('[data-page]')?.dataset.page,scroll={x:window.scrollX,y:window.scrollY};
 const keys=['action','id','tf','tab','order','filter','period','live','demoState'],identity=active?.dataset?Object.fromEntries(keys.filter(k=>active.dataset[k]!==undefined).map(k=>[k,active.dataset[k]])):null,wasArchive=active?.matches('details.archive > summary');
 state.view==='board'?renderBoard():renderWorkbench();
 for(const menu of app.querySelectorAll('.menu')){if(menu.getBoundingClientRect().bottom>window.innerHeight-8)menu.dataset.placement='above';}
 if(oldPage!==state.view){const main=app.querySelector('#main');main?.focus({preventScroll:true});window.scrollTo(0,0);return;}
 window.scrollTo(scroll.x,scroll.y);
 let target=wasArchive?app.querySelector('details.archive > summary'):null;
 if(identity&&Object.keys(identity).length){target=[...app.querySelectorAll('button,select,input')].find(node=>Object.entries(identity).every(([k,v])=>node.dataset[k]===v));if(!target&&identity.id)target=[...app.querySelectorAll('[data-action="menu"]')].find(node=>node.dataset.id===identity.id);}
 if(!target&&identity?.action?.startsWith('data-'))target=app.querySelector('[data-demo-state]');if(target)target.focus({preventScroll:true});
}
let lastFocus=null;
function closeModal(){modalRoot.innerHTML='';state.drawer=null;document.body.style.overflow='';lastFocus?.focus?.();}
function openModal(html,drawer=false){lastFocus=document.activeElement;document.body.style.overflow='hidden';modalRoot.innerHTML=`<div class="overlay ${drawer?'':'confirmoverlay'}" data-dismiss="true"><div class="${drawer?'drawer':'confirm'}" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1">${html}</div></div>`;const dialog=modalRoot.querySelector('[role=dialog]');(dialog.querySelector('button')||dialog).focus();}
function detail(id){state.menu=null;state.drawer=id;const sim=simBy(id),s=status(sim);openModal(`<header class="drawerhead"><div class="dialogtitle"><div><h2 id="dialog-title">运行详情</h2><div style="margin-top:8px">${badge(s)}</div><p class="mono muted" style="margin-top:8px">${esc(sim.runId||'尚未产生 run')}</p></div>${button('关闭','close','','aria-label="关闭运行详情"')}</div><div class="inlineactions" style="margin-top:16px">${DATA.SIM_DATA[id]?button('打开工作台','workbench','primary',`data-id="${id}"`):''}${button('导出','export','',`data-id="${id}" aria-label="导出运行事实" ${['preparing','draft'].includes(s)?'disabled':''}`)}</div>${liveStates.includes(s)?'<div class="statusline">进行中 · 截至最后确认事件</div>':''}</header><div class="drawerbody"><details open><summary>概览</summary><div class="sectionbody">${facts(sim)}<span class="tooltipwrap">${button('标识与快照','tooltip')}<span class="tooltip" role="tooltip">RunSpec / 策略内容 / runtime<br>当前示例未提供完整内容哈希，不补造。</span></span></div></details><details open><summary>执行</summary><div class="sectionbody"><p class="mono">${esc(sim.runId||'尚未产生 run')}</p><div class="note">${['preparing','draft'].includes(s)?'待启动 · 未产生执行事件':s==='failed'?'执行失败 · 缺失事实保留未取得':s==='completed'?'运行已结束 · 只读回看':'当前执行状态：'+esc(labels[s])}</div><details><summary>Lineage</summary><div class="tree">${esc(sim.strategy)}:${esc(sim.version)}<div>${esc(sim.runId||'尚无下游 run')}</div><div>上游内容哈希：未提供</div></div></details></div></details><details open><summary>账户与风险</summary><div class="sectionbody"><div class="kv"><div><small>持仓</small><p>${esc(sim.position?.text)}</p></div><div><small>日限额剩余</small><p>${esc(sim.dailyLimitLeft?.text)}</p></div></div><details><summary>诊断</summary><div class="note">未接入真实诊断；仅展示原示例事实。</div></details><details><summary>风控</summary><div class="note">${esc(sim.todayLoss?.text)} · ${esc(sim.dailyLimitLeft?.text)}</div></details></div></details><details open><summary>数据与证据</summary><div class="sectionbody">${sim.health.map(x=>`<div class="checkrow"><span>${esc(x.label)}</span><span class="${x.state==='ok'?'positive':'amber'}">${esc(x.state)}</span></div>`).join('')}<details><summary>质量与 Failure</summary><div class="note">证据：${esc(sim.evidence)}。未取得原始 Failure 详细字段，保留缺口。</div></details></div></details><details open><summary>时间线</summary><div class="sectionbody">${sim.runId?`<div class="timeline"><p class="mono">${esc(sim.runId)}</p><p>${esc(labels[s])} · ${esc(sim.lastMarketTime?.text)}</p></div>`:'<div class="empty">尚无运行事件</div>'}</div></details></div>`,true);}
function confirmStop(kind){const emergency=kind==='emergency';openModal(`<h2 id="dialog-title" class="${emergency?'negative':'amber'}">确认${emergency?'紧急':'正常'}停止</h2><p>${emergency?'立即停止新意图，尽快撤普通单。不创建平仓意图，不伪造 Flat。':'将停止产生新模拟意图，撤销普通挂单，保留并核对止盈止损保护订单。'}</p><p>${emergency?'若保护无法闭合，将进入「未完成收尾」状态。':'只有 Position Flat 且订单终态才显示「运行完成」。'}</p><p>本原型只改变当前页面的本地状态，不发送业务请求。</p><div class="confirmfooter">${button('取消','close')}${button('确认'+(emergency?'紧急':'正常')+'停止','confirm-stop','danger')}</div>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b){if(e.target.matches('[data-dismiss]'))closeModal();return;}const id=b.dataset.id,a=b.dataset.action;switch(a){case'board':closeModal();state.view='board';state.menu=null;render();break;case'workbench':closeModal();state.view='workbench';state.selected=id;state.tab='订单列表';state.order=0;state.tf='5m';state.collapsed=false;render();break;case'menu':state.menu=state.menu===id?null:id;render();break;case'filter':state.filter=b.dataset.filter;state.menu=null;render();break;case'period':state.periods[id]=b.dataset.period;render();break;case'detail':detail(id);break;case'close':closeModal();break;case'cancel-pending':openModal(`<h2 id="dialog-title">取消本次启动？</h2><p>保留配置与记录；该模拟移为「已取消」，可恢复待启动。</p><div class="confirmfooter">${button('返回','close')}${button('取消本次启动','confirm-cancel','danger',`data-id="${id}"`)}</div>`);break;case'confirm-cancel':state.cancelled.add(id);closeModal();render();announce('本次启动已取消，配置保留');break;case'restore-pending':state.cancelled.delete(id);render();announce('已恢复待启动');break;case'start':state.cancelled.delete(id);state.live[id]='running';render();announce('已进入本地运行演示；未发送业务请求');break;case'archive':archived.add(id);state.restored.delete(id);state.menu=null;state.archive=true;render();announce('记录已移至历史/归档');break;case'restore':state.restored.add(id);state.menu=null;render();announce('记录已恢复到模拟记录');break;case'tf':state.tf=b.dataset.tf;render();break;case'tab':state.tab=b.dataset.tab;render();break;case'order':state.order=Number(b.dataset.order);render();break;case'collapse':state.collapsed=!state.collapsed;render();break;case'normal':case'emergency':confirmStop(a);break;case'confirm-stop':state.stopped.add(state.selected);closeModal();render();announce('本地状态已为停止中；未确认 Flat');break;case'export':{const sim=simBy(id),blob=new Blob([JSON.stringify({source:'C09 local prototype example',sim},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=id+'-example.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}case'not-in-scope':openModal(`<h2 id="dialog-title">此原型范围为模拟记录与工作台</h2><p>策略列表与实盘驾驶舱不属于当前两页。</p><div class="confirmfooter">${button('返回模拟记录','close')}</div>`);break;case'log':openModal(`<h2 id="dialog-title">业务日志</h2><p>当前原型没有真实业务日志；可在「最新事件」查看已有示例运行事实。</p><div class="confirmfooter">${button('关闭','close')}</div>`);break;case'data-retry':enterDataState('loading');break;case'data-restore':enterDataState('ready');break;case'data-frozen':enterDataState('frozen');break;case'refresh':if(state.dataMode==='live-demo')enterDataState('loading');else announce('当前为固定示例数据，未发起网络刷新');break;case'health':case'tooltip':break;default:break;}});
document.addEventListener('input',e=>{if(e.target.matches('input[type=search]')){const pos=e.target.selectionStart;state.query=e.target.value;render();const input=app.querySelector('input[type=search]');input.focus();if(pos!==null)input.setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{if(e.target.matches('[data-demo-state]')){e.target.focus({preventScroll:true});enterDataState(e.target.value);return;}if(e.target.id==='sort'){state.sort=e.target.value;render();}if(e.target.dataset.live){state.live[e.target.dataset.live]=e.target.value;state.menu=null;render();}});
document.addEventListener('keydown',e=>{const dialog=modalRoot.querySelector('[role=dialog]');if(e.key==='Escape'){if(dialog)closeModal();else if(state.menu){state.menu=null;render();}}if(e.key==='Tab'&&dialog){const nodes=[...dialog.querySelectorAll('button:not(:disabled),a[href],input,select,summary,[tabindex="0"]')].filter(x=>x.getClientRects().length);if(!nodes.length){e.preventDefault();dialog.focus();}else if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0].focus();}}});
render();
